16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Digits;
22	import jakarta.validation.constraints.Email;
23	import jakarta.validation.constraints.NotEmpty;
24	import jakarta.validation.constraints.Pattern;
25	
26	import java.time.LocalDate;
27	import java.util.*;
28	
29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "telephone")
49	    @NotEmpty
50	    @Digits(fraction = 0, integer = 10)
51	    @Pattern(regexp = "^[0-9]{10}$", message = "Phone number must be exactly 10 digits")
52	    private String telephone;
53	
54	    @Column(name = "email")
55	    @Email
56	    private String email;
57	
58	    @Column(name = "registration_date")
59	    private LocalDate registrationDate;
60	
61	    @Column(name = "membership_number")
62	    private Integer membershipNumber;
63	
64	    @Column(name = "customer_code")
65	    private String customerCode;
66	
67	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
68	    private Set<Pet> pets;
69	
70	    public String getAddress() {
71	        return this.address;
72	    }
73	
74	    public void setAddress(String address) {
75	        this.address = address;
76	    }
77	
78	    public String getCity() {
79	        return this.city;
80	    }
81	
82	    public void setCity(String city) {
83	        this.city = city;
84	    }
85	
86	    public String getTelephone() {
87	        return this.telephone;
88	    }
89	
90	    public void setTelephone(String telephone) {
91	        // Store telephone numbers as digits only, stripping spaces, dashes and
92	        // parentheses so that formatted input such as "(613) 555-0100" is kept
93	        // and compared as "6135550100".
94	        this.telephone = telephone == null ? null : telephone.replaceAll("[\\s()-]", "");
95	    }
96	
97	    public String getEmail() {
98	        return this.email;
99	    }
100	
101	    public void setEmail(String email) {
102	        this.email = email;
103	    }
104	
105	    public LocalDate getRegistrationDate() {
106	        return this.registrationDate;
107	    }
108	
109	    public void setRegistrationDate(LocalDate registrationDate) {
110	        this.registrationDate = registrationDate;
111	    }
112	
113	    public Integer getMembershipNumber() {
114	        return this.membershipNumber;
115	    }
116	
117	    public void setMembershipNumber(Integer membershipNumber) {
118	        this.membershipNumber = membershipNumber;
119	    }
120	
121	    public String getCustomerCode() {
122	        return this.customerCode;
123	    }
124	
125	    public void setCustomerCode(String customerCode) {
126	        this.customerCode = customerCode;
127	    }
128	
129	    protected Set<Pet> getPetsInternal() {
130	        if (this.pets == null) {
131	            this.pets = new HashSet<>();
132	        }
133	        return this.pets;
134	    }
135	
136	    protected void setPetsInternal(Set<Pet> pets) {
137	        this.pets = pets;
138	    }
139	
140	    public List<Pet> getPets() {
141	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
142	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
143	        return Collections.unmodifiableList(sortedPets);
144	    }
145	
146	    public void setPets(List<Pet> pets) {
147	        this.pets = new HashSet<>(pets);
148	    }
149	
150	    public void addPet(Pet pet) {
151	        getPetsInternal().add(pet);
152	        pet.setOwner(this);
153	    }
154	
155	    /**
156	     * Return the Pet with the given name, or null if none found for this Owner.
157	     *
158	     * @param name to test
159	     * @return true if pet name is already in use
160	     */
161	    public Pet getPet(String name) {
162	        return getPet(name, false);
163	    }
164	
165	    /**
166	     * Return the Pet with the given name, or null if none found for this Owner.
167	     *
168	     * @param name to test
169	     * @return true if pet name is already in use
170	     */
171	    public Pet getPet(String name, boolean ignoreNew) {
172	        name = name.toLowerCase();
173	        for (Pet pet : getPetsInternal()) {
174	            if (!ignoreNew || !pet.isNew()) {
175	                String compName = pet.getName();
176	                compName = compName.toLowerCase();
177	                if (compName.equals(name)) {
178	                    return pet;
179	                }
180	            }
181	        }
182	        return null;
183	    }
184	
185	    public Pet getPet(Integer petId) {
186	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
187	    }
188	
189	    @Override
190	    public String toString() {
191	        return new ToStringCreator(this)
192	
193	            .append("id", this.getId())
194	            .append("new", this.isNew())
195	            .append("lastName", this.getLastName())
196	            .append("firstName", this.getFirstName())
197	            .append("address", this.address)
198	            .append("city", this.city)
199	            .append("telephone", this.telephone)
200	            .toString();
201	    }
202	}
