16	package org.springframework.samples.petclinic.service;
17	
18	import org.springframework.dao.DataAccessException;
19	import org.springframework.dao.EmptyResultDataAccessException;
20	import org.springframework.data.domain.Page;
21	import org.springframework.data.domain.Pageable;
22	import org.springframework.orm.ObjectRetrievalFailureException;
23	import org.springframework.samples.petclinic.model.*;
24	import org.springframework.samples.petclinic.repository.*;
25	import org.springframework.stereotype.Service;
26	import org.springframework.transaction.annotation.Transactional;
27	
28	import java.time.LocalDate;
29	import java.util.Collection;
30	import java.util.List;
31	import java.util.Objects;
32	import java.util.Set;
33	import java.util.function.Supplier;
34	
35	/**
36	 * Mostly used as a facade for all Petclinic controllers
37	 * Also a placeholder for @Transactional and @Cacheable annotations
38	 *
39	 * @author Michael Isvy
40	 * @author Vitaliy Fedoriv
41	 */
42	@Service
43	public class ClinicServiceImpl implements ClinicService {
44	
45	    private final PetRepository petRepository;
46	    private final VetRepository vetRepository;
47	    private final OwnerRepository ownerRepository;
48	    private final VisitRepository visitRepository;
49	    private final SpecialtyRepository specialtyRepository;
50	    private final PetTypeRepository petTypeRepository;
51	
52	    public ClinicServiceImpl(
53	        PetRepository petRepository,
54	        VetRepository vetRepository,
55	        OwnerRepository ownerRepository,
56	        VisitRepository visitRepository,
57	        SpecialtyRepository specialtyRepository,
58	        PetTypeRepository petTypeRepository) {
59	        this.petRepository = petRepository;
60	        this.vetRepository = vetRepository;
61	        this.ownerRepository = ownerRepository;
62	        this.visitRepository = visitRepository;
63	        this.specialtyRepository = specialtyRepository;
64	        this.petTypeRepository = petTypeRepository;
65	    }
66	
67	    @Override
68	    @Transactional(readOnly = true)
69	    public Collection<Pet> findAllPets() throws DataAccessException {
70	        return petRepository.findAll();
71	    }
72	
73	    @Override
74	    @Transactional(readOnly = true)
75	    public Page<Pet> findPets(Pageable pageable) throws DataAccessException {
76	        return petRepository.findAll(pageable);
77	    }
78	
79	    @Override
80	    @Transactional
81	    public void deletePet(Pet pet) throws DataAccessException {
82	        petRepository.delete(pet);
83	    }
84	
85	    @Override
86	    @Transactional(readOnly = true)
87	    public Visit findVisitById(int visitId) throws DataAccessException {
88	        return findEntityById(() -> visitRepository.findById(visitId));
89	    }
90	
91	    @Override
92	    @Transactional(readOnly = true)
93	    public Collection<Visit> findAllVisits() throws DataAccessException {
94	        return visitRepository.findAll();
95	    }
96	
97	    @Override
98	    @Transactional
99	    public void deleteVisit(Visit visit) throws DataAccessException {
100	        visitRepository.delete(visit);
101	    }
102	
103	    @Override
104	    @Transactional(readOnly = true)
105	    public Vet findVetById(int id) throws DataAccessException {
106	        return findEntityById(() -> vetRepository.findById(id));
107	    }
108	
109	    @Override
110	    @Transactional(readOnly = true)
111	    public Collection<Vet> findAllVets() throws DataAccessException {
112	        return vetRepository.findAll();
113	    }
114	
115	    @Override
116	    @Transactional
117	    public void saveVet(Vet vet) throws DataAccessException {
118	        vetRepository.save(vet);
119	    }
120	
121	    @Override
122	    @Transactional
123	    public void deleteVet(Vet vet) throws DataAccessException {
124	        vetRepository.delete(vet);
125	    }
126	
127	    @Override
128	    @Transactional(readOnly = true)
129	    public Collection<Owner> findAllOwners() throws DataAccessException {
130	        return ownerRepository.findAll();
131	    }
132	
133	    @Override
134	    @Transactional(readOnly = true)
135	    public Page<Owner> findOwners(String lastName, Pageable pageable) throws DataAccessException {
136	        if (lastName != null) {
137	            return ownerRepository.findByLastName(lastName, pageable);
138	        }
139	        return ownerRepository.findAll(pageable);
140	    }
141	
142	    @Override
143	    @Transactional
144	    public void deleteOwner(Owner owner) throws DataAccessException {
145	        ownerRepository.delete(owner);
146	    }
147	
148	    @Override
149	    @Transactional(readOnly = true)
150	    public PetType findPetTypeById(int petTypeId) {
151	        return findEntityById(() -> petTypeRepository.findById(petTypeId));
152	    }
153	
154	    @Override
155	    @Transactional(readOnly = true)
156	    public Collection<PetType> findAllPetTypes() throws DataAccessException {
157	        return petTypeRepository.findAll();
158	    }
159	
160	    @Override
161	    @Transactional
162	    public void savePetType(PetType petType) throws DataAccessException {
163	        petTypeRepository.save(petType);
164	    }
165	
166	    @Override
167	    @Transactional
168	    public void deletePetType(PetType petType) throws DataAccessException {
169	        petTypeRepository.delete(petType);
170	    }
171	
172	    @Override
173	    @Transactional(readOnly = true)
174	    public Specialty findSpecialtyById(int specialtyId) {
175	        return findEntityById(() -> specialtyRepository.findById(specialtyId));
176	    }
177	
178	    @Override
179	    @Transactional(readOnly = true)
180	    public Collection<Specialty> findAllSpecialties() throws DataAccessException {
181	        return specialtyRepository.findAll();
182	    }
183	
184	    @Override
185	    @Transactional
186	    public void saveSpecialty(Specialty specialty) throws DataAccessException {
187	        specialtyRepository.save(specialty);
188	    }
189	
190	    @Override
191	    @Transactional
192	    public void deleteSpecialty(Specialty specialty) throws DataAccessException {
193	        specialtyRepository.delete(specialty);
194	    }
195	
196	    @Override
197	    @Transactional(readOnly = true)
198	    public Collection<PetType> findPetTypes() throws DataAccessException {
199	        return petRepository.findPetTypes();
200	    }
201	
202	    @Override
203	    @Transactional(readOnly = true)
204	    public Owner findOwnerById(int id) throws DataAccessException {
205	        return findEntityById(() -> ownerRepository.findById(id));
206	    }
207	
208	    @Override
209	    @Transactional(readOnly = true)
210	    public Pet findPetById(int id) throws DataAccessException {
211	        return findEntityById(() -> petRepository.findById(id));
212	    }
213	
214	    @Override
215	    @Transactional
216	    public void savePet(Pet pet) throws DataAccessException {
217	        pet.setType(findPetTypeById(pet.getType().getId()));
218	        petRepository.save(pet);
219	    }
220	
221	    @Override
222	    @Transactional
223	    public void saveVisit(Visit visit) throws DataAccessException {
224	        visitRepository.save(visit);
225	
226	    }
227	
228	    @Override
229	    @Transactional(readOnly = true)
230	    public Collection<Vet> findVets() throws DataAccessException {
231	        return vetRepository.findAll();
232	    }
233	
234	    @Override
235	    @Transactional
236	    public void saveOwner(Owner owner) throws DataAccessException {
237	        if (owner.isNew() && isDuplicateEmail(owner)) {
238	            throw new DuplicateOwnerException(
239	                "An owner with the same email already exists");
240	        }
241	        if (owner.isNew() && isDuplicateTelephone(owner)) {
242	            throw new DuplicateOwnerException(
243	                "An owner with the same telephone already exists");
244	        }
245	        if (owner.isNew() && isDuplicateOwner(owner)) {
246	            throw new DuplicateOwnerException(
247	                "An owner with the same last name and telephone already exists");
248	        }
249	        if (owner.isNew() && cityOwnerLimitReached(owner)) {
250	            throw new CityOwnerLimitExceededException(
251	                "The maximum number of owners that can be registered in this city has been reached");
252	        }
253	        if (owner.getRegistrationDate() == null) {
254	            owner.setRegistrationDate(LocalDate.now());
255	        }
256	        if (owner.isNew() && dailyRegistrationLimitReached(owner.getRegistrationDate())) {
257	            throw new DailyOwnerRegistrationLimitExceededException(
258	                "The maximum number of owners that can be registered today has been reached");
259	        }
260	        ownerRepository.save(owner);
261	
262	    }
263	
264	    private boolean isDuplicateEmail(Owner owner) {
265	        if (owner.getEmail() == null) {
266	            return false;
267	        }
268	        String email = normalizeKey(owner.getEmail());
269	        return ownerRepository.findAll().stream()
270	            .anyMatch(existing -> !existing.getId().equals(owner.getId())
271	                && Objects.equals(normalizeKey(existing.getEmail()), email));
272	    }
273	
274	    private boolean isDuplicateTelephone(Owner owner) {
275	        if (owner.getTelephone() == null) {
276	            return false;
277	        }
278	        String telephone = normalizeKey(owner.getTelephone());
279	        return ownerRepository.findAll().stream()
280	            .anyMatch(existing -> !existing.getId().equals(owner.getId())
281	                && Objects.equals(normalizeKey(existing.getTelephone()), telephone));
282	    }
283	
284	    /**
285	     * The maximum number of owners that may be registered on a single calendar day (by registration
286	     * date). Attempts to register more than this in a day are rejected.
287	     */
288	    private static final long MAX_OWNERS_PER_DAY = 20;
289	
290	    private boolean dailyRegistrationLimitReached(LocalDate registrationDate) {
291	        if (registrationDate == null) {
292	            return false;
293	        }
294	        long registeredOnDay = ownerRepository.findAll().stream()
295	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
296	            .count();
297	        return registeredOnDay >= MAX_OWNERS_PER_DAY;
298	    }
299	
300	    /**
301	     * The maximum number of owners that may reside in a single city. Once a city already contains
302	     * this many owners, attempts to register a further owner in that city are rejected.
303	     */
304	    private static final long MAX_OWNERS_PER_CITY = 8;
305	
306	    private boolean cityOwnerLimitReached(Owner owner) {
307	        if (owner.getCity() == null) {
308	            return false;
309	        }
310	        String city = normalizeKey(owner.getCity());
311	        long ownersInCity = ownerRepository.findAll().stream()
312	            .filter(existing -> !existing.getId().equals(owner.getId())
313	                && Objects.equals(normalizeKey(existing.getCity()), city))
314	            .count();
315	        return ownersInCity >= MAX_OWNERS_PER_CITY;
316	    }
317	
318	    private boolean isDuplicateOwner(Owner owner) {
319	        if (owner.getLastName() == null) {
320	            return false;
321	        }
322	        String lastName = normalizeKey(owner.getLastName());
323	        String telephone = normalizeKey(owner.getTelephone());
324	        return ownerRepository.findAll().stream()
325	            .anyMatch(existing -> !existing.getId().equals(owner.getId())
326	                && Objects.equals(normalizeKey(existing.getLastName()), lastName)
327	                && Objects.equals(normalizeKey(existing.getTelephone()), telephone));
328	    }
329	
330	    /**
331	     * Normalizes a value for duplicate detection so that comparisons ignore
332	     * letter case and surrounding or repeated whitespace (e.g. {@code
333	     * "  john   smith "} and {@code "John Smith"} are treated as equal).
334	     */
335	    private static String normalizeKey(String value) {
336	        if (value == null) {
337	            return null;
338	        }
339	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
340	    }
341	
342	    @Override
343	    @Transactional(readOnly = true)
344	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
345	        return ownerRepository.findByLastName(lastName);
346	    }
347	
348	    @Override
349	    @Transactional(readOnly = true)
350	    public Collection<Visit> findVisitsByPetId(int petId) {
351	        return visitRepository.findByPetId(petId);
352	    }
353	
354	    @Override
355	    @Transactional(readOnly = true)
356	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
357	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
358	    }
359	
360	    private <T> T findEntityById(Supplier<T> supplier) {
361	        try {
362	            return supplier.get();
363	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
364	            // Just ignore not found exceptions for Jdbc/Jpa realization
