1	package org.springframework.samples.petclinic.acceptance;
2	
3	import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
4	import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
5	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
6	
7	import java.time.LocalDate;
8	import java.util.concurrent.atomic.AtomicInteger;
9	
10	import org.springframework.beans.factory.annotation.Autowired;
11	import org.springframework.boot.test.context.SpringBootTest;
12	import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
13	import org.springframework.http.MediaType;
14	import org.springframework.security.test.context.support.WithMockUser;
15	import org.springframework.test.web.servlet.MockMvc;
16	import org.springframework.test.web.servlet.ResultActions;
17	import org.springframework.transaction.annotation.Transactional;
18	
19	import tools.jackson.databind.JsonNode;
20	import tools.jackson.databind.ObjectMapper;
21	import tools.jackson.databind.node.ObjectNode;
22	
23	/**
24	 * Experimenter-owned, black-box acceptance base for PetClinic-Evolve.
25	 *
26	 * <p>Every checkpoint is a business rule on the ONE endpoint {@code POST /api/owners};
27	 * tests create owners and read fields back via {@code GET /api/owners/{id}}, so the
28	 * Spring and OfficeFloor arms are judged by identical externals.
29	 *
30	 * <p>Isolation: {@code @Transactional} rolls each test back, so count/quota rules
31	 * (membership number, per-day cap, per-city cap, "most common city") see only the
32	 * seed data plus what the test itself creates — deterministic without polluting
33	 * other tests. {@code @WithMockUser} authenticates as a fixed admin so the audit
34	 * rules can assert a known user name.
35	 *
36	 * <p>Cumulative-safety convention: {@link #ownerNode()} returns a FULLY UNIQUE
37	 * owner, which every rule accepts (no duplicate, no quota) at every checkpoint;
38	 * tests then override only the fields needed to trigger a specific rule. Reject
39	 * cases use data that stays rejected under all later (broader) rules.
40	 */
41	@SpringBootTest
42	@AutoConfigureMockMvc
43	@Transactional
44	@WithMockUser(username = "acceptance-admin", roles = {"OWNER_ADMIN", "VET_ADMIN", "ADMIN"})
45	public abstract class AcceptanceBase {
46	
47		private static final AtomicInteger SEQ = new AtomicInteger(0);
48	
49		@Autowired
50		protected MockMvc mvc;
51	
52		@Autowired
53		protected ObjectMapper om;
54	
55		protected int seq() {
56			return SEQ.incrementAndGet();
57		}
58	
59		// --- unique generators (avoid colliding with seed data or other tests) ---
60	
61		/** Encode n as a lowercase letter string (1->a, 26->z, 27->aa), so generated
62		 *  names satisfy the base app's letters-only owner-name pattern. */
63		protected String letters(int n) {
64			StringBuilder sb = new StringBuilder();
65			for (int x = Math.max(n, 1); x > 0; x /= 26) {
66				x--;
67				sb.insert(0, (char) ('a' + x % 26));
68			}
69			return sb.toString();
70		}
71	
72		/** Unique, letters-only surname (starts with "Sur"). */
73		protected String uniqueLastName() {
74			return "Sur" + letters(seq());
75		}
76	
77		protected String uniqueAddress() {
78			return seq() + " Test Street";
79		}
80	
81		protected String uniqueCity() {
82			return "Town" + seq();
83		}
84	
85		/** A unique 10-digit telephone starting with 2 (seed uses 6xxxxxxxxx). */
86		protected String uniqueTelephone() {
87			return String.format("2%09d", seq());
88		}
89	
90		protected String uniqueEmail() {
91			return "owner" + seq() + "@example.test";
92		}
93	
94		protected String today() {
95			return LocalDate.now().toString();
96		}
97	
98		// --- payloads -----------------------------------------------------------
99	
100		/** A fully valid, fully unique owner — accepted by every rule at every checkpoint. */
101		protected ObjectNode ownerNode() {
102			ObjectNode o = om.createObjectNode();
103			o.put("firstName", "Test");
104			o.put("lastName", uniqueLastName());
105			o.put("address", uniqueAddress());
106			o.put("city", uniqueCity());
107			o.put("telephone", uniqueTelephone());
108			return o;
109		}
110	
111		// --- requests -----------------------------------------------------------
112	
113		protected String json(JsonNode node) {
114			try {
115				return om.writeValueAsString(node);
116			}
117			catch (Exception e) {
118				throw new RuntimeException(e);
119			}
120		}
121	
122		protected ResultActions createOwner(JsonNode body) throws Exception {
123			return mvc.perform(post("/api/owners").contentType(MediaType.APPLICATION_JSON)
124					.content(json(body)));
125		}
126	
127		protected int createOwnerOk(JsonNode body) throws Exception {
128			return extractId(createOwner(body).andExpect(status().is2xxSuccessful()));
129		}
130	
131		protected ResultActions getOwner(int id) throws Exception {
132			return mvc.perform(get("/api/owners/" + id));
133		}
134	
135		/** GET the owner and return its JSON body (asserts 2xx). */
136		protected JsonNode fetchOwner(int id) throws Exception {
137			String body = getOwner(id).andExpect(status().is2xxSuccessful())
138					.andReturn().getResponse().getContentAsString();
139			return om.readTree(body);
140		}
141	
142		protected int extractId(ResultActions ra) throws Exception {
143			String body = ra.andReturn().getResponse().getContentAsString();
144			if (body != null && !body.isBlank()) {
145				JsonNode n = om.readTree(body);
146				if (n.hasNonNull("id")) {
147					return n.get("id").asInt();
148				}
149			}
150			String location = ra.andReturn().getResponse().getHeader("Location");
151			if (location != null && location.contains("/")) {
152				return Integer.parseInt(location.substring(location.lastIndexOf('/') + 1));
153			}
154			throw new IllegalStateException("no id in create response: " + body);
155		}
156	}
